update pages set contenu = '{"gabarit":"fiche","chapeau":"GLS, acteur reconnu de la logistique et du transport, a confié à Migen le maintien opérationnel de ses équipements. Deux techniciens expérimentés sont aujourd''hui en poste sur le site.","fiche":[],"contexte":"**Un trieur à l''arrêt, ce sont des colis qui partent en retard et un client final qui le voit.** La panne ne reste jamais dans l''atelier.\nChez GLS, la disponibilité des équipements est un enjeu quotidien :\n**Les flux du site entier sont touchés** dès qu''un arrêt non planifié survient.\n**L''acheminement des colis prend du retard** au moment où la ligne s''immobilise.\n**La satisfaction client encaisse** directement ces retards.\n**Les équipements critiques sont nombreux** : convoyeurs, trieurs, packaging automatisé.","intervention":"**Deux techniciens dédiés** : Affectés à la maintenance curative et à la surveillance continue des équipements critiques du site.\n**Une présence permanente** : Les équipes Migen sont sur place en continu, pour tenir la disponibilité des installations logistiques.\n**Une réaction sans déplacement** : Le dysfonctionnement est traité au moment où il se produit, par quelqu''un qui est déjà là.\n**Une intégration aux équipes GLS** : Les techniciens travaillent au sein de l''organisation existante, sans la complexifier.\n**Des horaires calés sur l''exploitation** : La couverture porte sur la semaine, les horaires décalés et le week-end.","resultats":[]}'::jsonb where path = '/preuves/gls-maintenance-curative/';
update pages set contenu = jsonb_set(contenu, '{fiche}', (contenu->'fiche') || '[{"libelle":"Client","valeur":"GLS, logistique et transport"},{"libelle":"Année","valeur":"2025"},{"libelle":"Effectif Migen","valeur":"2 techniciens expérimentés sur site"},{"libelle":"Nature des travaux","valeur":"Maintenance curative, surveillance continue"},{"libelle":"Périmètre","valeur":"Convoyeurs, trieurs, systèmes de packaging automatisés"},{"libelle":"Couverture","valeur":"Semaine, horaires décalés, week-end"},{"libelle":"Pilotage","valeur":"Suivi de prestation assuré par Migen"}]'::jsonb) where path = '/preuves/gls-maintenance-curative/';
update pages set contenu = jsonb_set(contenu, '{resultats}', (contenu->'resultats') || '[{"valeur":"Des temps d''arrêt réduits","libelle":"La présence continue des techniciens permet à GLS de raccourcir ses arrêts."},{"valeur":"Des installations plus performantes","libelle":"La performance des installations logistiques augmente."},{"valeur":"Un flux plus fluide","libelle":"Le flux opérationnel du site est maintenu, jour après jour."}]'::jsonb) where path = '/preuves/gls-maintenance-curative/';
